/**
 * QiLin host shim for dsh-atomic-write (H5-d slice 2): temp-file + rename.
 * Supports the 3-arg form used by dsh-file-review-tab
 * writeFileAtomic(file, content, { mode }).
 */
import { writeFileSync, renameSync } from "node:fs";

export async function writeFileAtomic(file, content, options = {}) {
  const tmp = file + ".awtmp-" + process.pid;
  const opts = options.mode ? { mode: options.mode } : undefined;
  writeFileSync(tmp, content, opts);
  renameSync(tmp, file);
}
